// Parse CSV URLhaus: skip baris komentar (#), ambil URL, filter malware_download.
const body = $input.first().json.body ?? $input.first().json.data ?? '';
const text = String(body);
const lines = text.split(/\r?\n/);
const MAX = 15;  // batch kecil per siklus (hormati rate-limit GSB)
const out = [];
for (const rawLine of lines) {
  const line = rawLine.replace(/\r$/, '').trim();
  if (!line || line.startsWith('#')) continue;
  // CSV: "id","dateadded","url","url_status","last_online","threat","tags","urlhaus_link","reporter"
  // Pecah manual per kolom bertanda kutip (robust thd koma dalam tanda kutip).
  const cols = [];
  const re = /"((?:[^"\\]|\\.)*)"/g;
  let m;
  while ((m = re.exec(line)) !== null) cols.push(m[1]);
  if (cols.length < 6) continue;
  const [id, dateadded, url, url_status, last_online, threat] = cols;
  if (threat !== 'malware_download') continue;   // fokus payload URL malware
  if (!/^https?:\/\//i.test(url)) continue;
  out.push({ json: { url, url_id: id, threat, tags: cols[6] || '', dateadded, urlhaus_link: cols[7] || '' } });
  if (out.length >= MAX) break;
}
return out;

const urls = $input.all();
const sd = $getWorkflowStaticData('global');
sd.proaktifCache = sd.proaktifCache || {};
const TTL = 24 * 60 * 60 * 1000;
const now = Date.now();
for (const [k, v] of Object.entries(sd.proaktifCache)) {
  if (!v || (now - (v.ts || 0)) > TTL) delete sd.proaktifCache[k];
}
const keys = Object.keys(sd.proaktifCache);
if (keys.length > 500) {
  for (const k of keys.slice(0, keys.length - 500)) delete sd.proaktifCache[k];
}

const GSB_LABEL = {
  SOCIAL_ENGINEERING: 'Phishing',
  MALWARE: 'Malware',
  UNWANTED_SOFTWARE: 'Unwanted software',
  POTENTIALLY_HARMFUL_APPLICATION: 'Aplikasi berbahaya',
};

const fleetToken = ($env.FLEET_COMMAND_TOKEN || '').trim();
const fleetHeaders = Object.assign({ 'Content-Type': 'application/json' }, fleetToken ? { 'Authorization': 'Bearer ' + fleetToken } : {});

let activeWazuhIds = [];
let activeRustIds = [];
try {
  const fl = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://host.docker.internal:8080/api/fleet',
    headers: fleetHeaders,
    timeout: 8000,
  });
  for (const a of (fl?.agents || [])) {
    if (String(a.status || '').toLowerCase() !== 'active') continue;
    if (a.type === 'rust') activeRustIds.push(String(a.id));
    else activeWazuhIds.push(String(a.id));
  }
} catch (e) {}

async function getWazuhToken() {
  const r = await this.helpers.httpRequestWithAuthentication.call(this, 'httpBasicAuth', {
    method: 'POST',
    url: 'https://host.docker.internal:55000/security/user/authenticate',
    body: {},
    json: true,
    rejectUnauthorized: false,
  });
  return r && r.data ? r.data.token : '';
}

let wazuhToken = null;
const blocked = [];
const review = [];
let checked = 0;

for (const item of urls) {
  const alert = item.json;
  const url = alert.url;
  if (!url) continue;
  checked++;

  const cached = sd.proaktifCache[url];
  if (cached && (Date.now() - (cached.ts || 0)) < TTL) continue;

  let gsb_threat = false, gsb_type = '';
  try {
    const g = await this.helpers.httpRequestWithAuthentication.call(this, 'httpQueryAuth', {
      method: 'POST',
      url: 'https://safebrowsing.googleapis.com/v4/threatMatches:find',
      body: {
        client: { clientId: 'soar-proaktif', clientVersion: '1.0' },
        threatInfo: {
          threatTypes: ['MALWARE', 'SOCIAL_ENGINEERING', 'UNWANTED_SOFTWARE', 'POTENTIALLY_HARMFUL_APPLICATION'],
          platformTypes: ['ANY_PLATFORM'],
          threatEntryTypes: ['URL'],
          threatEntries: [{ url }],
        },
      },
      json: true,
      timeout: 15000,
    });
    if (g && Array.isArray(g.matches) && g.matches.length > 0) {
      gsb_threat = true;
      gsb_type = g.matches[0].threatType || 'THREAT';
    }
  } catch (e) {}

  sd.proaktifCache[url] = { ts: Date.now(), gsb_threat, gsb_type };
  if (!gsb_threat) continue;

  let domain = '';
  try { domain = new URL(url).hostname.toLowerCase(); } catch (e) {}
  if (!domain || /^\d+\.\d+\.\d+\.\d+$/.test(domain)) {
    review.push({ url, type: GSB_LABEL[gsb_type] || gsb_type, reason: 'IP literal' });
    continue;
  }

  let okCount = 0;
  if (activeWazuhIds.length > 0) {
    try {
      if (!wazuhToken) wazuhToken = await getWazuhToken.call(this);
      await this.helpers.httpRequest({
        method: 'PUT',
        url: 'https://host.docker.internal:55000/active-response?agents_list=' + activeWazuhIds.join(','),
        headers: { 'Authorization': 'Bearer ' + wazuhToken, 'Content-Type': 'application/json' },
        body: JSON.stringify({ command: '!block-domain', arguments: [domain] }),
        rejectUnauthorized: false,
        timeout: 20000,
      });
      okCount += activeWazuhIds.length;
    } catch (e) {}
  }

  for (const rid of activeRustIds) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://host.docker.internal:8080/api/commands',
        headers: fleetHeaders,
        body: JSON.stringify({ agent_id: rid, action: 'sinkhole', target: domain, by: 'proaktif-phishing' }),
        timeout: 8000,
      });
      okCount++;
    } catch (e) {}
  }

  blocked.push({ url, domain, type: GSB_LABEL[gsb_type] || gsb_type, agents: okCount });
}

if (blocked.length === 0 && review.length === 0) return [];
return [{ json: { checked, blocked, review } }];
